#### ApiKeyController.php

This controller will handle the API key validation and saving.

```php
// app/Http/Controllers/ApiKeyController.php
namespace App\Http\Controllers;

use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Http;

class ApiKeyController extends Controller
{
    public function index()
    {
        // Check if the API key exists in the database
        $apiKey = DB::table('mailerlite_keys')->first();

        return view('api-key', ['apiKey' => $apiKey]);
    }

    public function validateApiKey(Request $request)
    {
        $apiKey = $request->input('api_key');

        // Validate the API key against MailerLite API
        $response = Http::withHeaders([
            'X-MailerLite-ApiKey' => $apiKey,
        ])->get('https://api.mailerlite.com/api/v2/me');

        if ($response->successful()) {
            // Save the API key to the database
            DB::table('mailerlite_keys')->insert([
                'api_key' => $apiKey,
                'created_at' => now(),
                'updated_at' => now(),
            ]);

            return redirect()->route('api-key')->with('success', 'API key validated and saved successfully.');
        } else {
            return redirect()->route('api-key')->with('error', 'Invalid API key. Please try again.');
        }
    }
}
```

#### SubscriberController.php

This controller will handle the DataTable, creating, deleting, and editing subscribers.

```php
// app/Http/Controllers/SubscriberController.php
namespace App\Http\Controllers;

use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Http;

class SubscriberController extends Controller
{
    public function index()
    {
        return view('subscribers');
    }

    public function getSubscribers(Request $request)
    {
        $apiKey = DB::table('mailerlite_keys')->value('api_key');

        $response = Http::withHeaders([
            'X-MailerLite-ApiKey' => $apiKey,
        ])->get('https://api.mailerlite.com/api/v2/subscribers');

        $subscribers = $response->json();

        // Format the date and time
        foreach ($subscribers as &$subscriber) {
            $subscriber['subscribe_date'] = date('d/m/Y', strtotime($subscriber['created_at']));
            $subscriber['subscribe_time'] = date('H:i', strtotime($subscriber['created_at']));
        }

        return response()->json([
            'data' => $subscribers,
            'draw' => $request->get('draw'),
            'recordsTotal' => count($subscribers),
            'recordsFiltered' => count($subscribers),
        ]);
    }

    public function store(Request $request)
    {
        $validated = $request->validate([
            'email' => 'required|email',
            'name' => 'required',
            'country' => 'required',
        ]);

        $apiKey = DB::table('mailerlite_keys')->value('api_key');

        $response = Http::withHeaders([
            'X-MailerLite-ApiKey' => $apiKey,
        ])->post('https://api.mailerlite.com/api/v2/subscribers', [
            'email' => $validated['email'],
            'name' => $validated['name'],
            'country' => $validated['country'],
        ]);

        if ($response->successful()) {
            return redirect()->route('subscribers')->with('success', 'Subscriber created successfully.');
        } else {
            return redirect()->route('subscribers')->with('error', 'Failed to create subscriber. Please check the details.');
        }
    }

    public function destroy($id)
    {
        $apiKey = DB::table('mailerlite_keys')->value('api_key');

        $response = Http::withHeaders([
            'X-MailerLite-ApiKey' => $apiKey,
        ])->delete("https://api.mailerlite.com/api/v2/subscribers/{$id}");

        if ($response->successful()) {
            return response()->json(['success' => true]);
        } else {
            return response()->json(['success' => false]);
        }
    }

    public function edit($id)
    {
        $apiKey = DB::table('mailerlite_keys')->value('api_key');

        $response = Http::withHeaders([
            'X-MailerLite-ApiKey' => $apiKey,
        ])->get("https://api.mailerlite.com/api/v2/subscribers/{$id}");

        $subscriber = $response->json();

        return view('edit-subscriber', ['subscriber' => $subscriber]);
    }

    public function update(Request $request, $id)
    {
        $validated = $request->validate([
            'name' => 'required',
            'country' => 'required',
        ]);

        $apiKey = DB::table('mailerlite_keys')->value('api_key');

        $response = Http::withHeaders([
            'X-MailerLite-ApiKey' => $apiKey,
        ])->put("https://api.mailerlite.com/api/v2/subscribers/{$id}", [
            'name' => $validated['name'],
            'country' => $validated['country'],
        ]);

        if ($response->successful()) {
            return redirect()->route('subscribers')->with('success', 'Subscriber updated successfully.');
        } else {
            return redirect()->route('subscribers')->with('error', 'Failed to update subscriber. Please check the details.');
        }
    }
}
```

